  ('24849253-5265-4445-b3a9-31dad5012219', 'e4f5a6b7-8c9d-4f44-9a34-5b6c7d8e9f44', null, 'topic'::public.curated_course_node_type, 'Foundations of Victimology: History, Scope, Concepts, and Debates', 'This opening unit introduces victimology as the study of victimization, harm, rights, services, and social response. Students learn how the field emerged and why it must avoid victim blaming while still explaining patterns of risk.', 0),
  ('fc40959d-01ac-4509-8e69-63983b8dd0ba', 'e4f5a6b7-8c9d-4f44-9a34-5b6c7d8e9f44', '24849253-5265-4445-b3a9-31dad5012219', 'subtopic'::public.curated_course_node_type, 'Origins and Scope', 'Students learn how victimology developed from criminology, victims'' rights movements, and social-service practice.', 0),
