dural fairness"}], "description": "Students examine the promise and limits of monetary and procedural remedies."}]}, {"id": "a3d36fe5-5727-4d15-8eb0-67a5b16a6cb0", "type": "topic", "title": "Victim Services, Advocacy, Case Management, Confidentiality, and Ethics", "description": "Victim services connect people to safety, information, healing, and resources. Students learn service models, ethics, boundaries, and coordinated care.", "children": [{"id": "4e76dc50-bef2-441d-b026-aa2e7ac14d93", "type": "subtopic", "title": "Advocacy Models", "children": [{"id": "f22f40a0-5680-441f-8404-17bd38dcb4bf", "type": "concept", "title": "Crisis intervention"}, {"id": "53bf2b58-7e3e-4d46-b908-9ea51b8f9d15", "type": "concept", "title": "Court advocacy"}, {"id": "60144882-43df-4e43-9419-abd647193a93", "type": "concept", "title": "Community-based services"}], "description": "Students compare crisis, systems, legal, and community advocacy."}, {"id": "d4cd3fbb-8808-4d8e-aada-e17971ff5a18", "type": "subtopic", "title": "Case Management and Referrals", "children": [{"id": "97e75c6a-562a-41c9-adce-7b2cce3fa6cc", "type": "concept", "title": "Needs assessment"}, {"id": "591b3b5a-74c8-4cea-8a78-f654aba10724", "type": "concept", "title": "Warm referrals"}, {"id": "1b0d559b-126c-478f-8758-c5caee6a8e80", "type": "concept", "title": "Safety and resource planning"}], "description": "The point is to build practical service-navigation skill."}, {"id": "39b125a8-c77b-48a0-98b8-8aa99aef00f3", "type": "subtopic", "title": "Ethics and Confidentiality", "children": [{"id": "d13a1769-04a9-482d-8167-6b39724c809e", "type": "concept", "title": "Informed consent"}, {"id": "abb72e03-1fe0-4f16-8f1d-03c777087821", "type": "concept", "title": "Mandated reporting"}, {"id": "39e0c66a-ea81-430c-a650-597eda0093f5", "type": "concept", "title": "Documentation and boundaries"}], "description": "Students learn ethical duties in helping relationships."}]}, {"id": "68595452-9653-4137-9485-e97e370ff1de", "type": "topic", "