"concept", "title": "Physical and emotional abuse"}, {"id": "9b8d43af-52c1-41d3-bfe1-28b98ce4d8d2", "type": "concept", "title": "Neglect"}, {"id": "d092f6e5-ade8-407f-a3ad-368b32f53a4e", "type": "concept", "title": "Financial exploitation"}], "description": "Students learn common forms and detection challenges."}, {"id": "bbf776f8-a939-436c-8c8e-1336ab68aa32", "type": "subtopic", "title": "Disability and Vulnerability", "children": [{"id": "3bc91a0d-d448-40f0-a214-e45e636f8956", "type": "concept", "title": "Communication access"}, {"id": "ef5b4b4e-b60c-49c8-8c39-beedcf447db9", "type": "concept", "title": "Caregiver dependence"}, {"id": "6eeed492-e9e8-4d47-8cfa-7ea75e631dd1", "type": "concept", "title": "Institutional abuse"}], "description": "The point is to understand access, autonomy, and abuse risk without paternalism."}, {"id": "e98c53e4-5893-4581-b727-d505a5240bf6", "type": "subtopic", "title": "Adult Protective and Legal Systems", "children": [{"id": "3385ba32-ea53-4764-9be2-83ee76ba87c3", "type": "concept", "title": "Capacity and consent"}, {"id": "d349510d-ea04-4da2-ba72-95a6988b0767", "type": "concept", "title": "Guardianship abuse"}, {"id": "6a80e6e8-61a9-45b8-a4d5-32b9ecad8253", "type": "concept", "title": "Mandatory reporting and APS"}], "description": "Students connect victim needs with legal remedies."}]}, {"id": "f600b932-a211-4382-95a6-323ca6ddd069", "type": "topic", "title": "Human Trafficking, Labor Exploitation, Sex Trafficking, and Migrant Victimization", "description": "Trafficking and exploitation involve coercion, dependency, and structural vulnerability. Students learn indicators, service needs, and survivor-centered response.", "children": [{"id": "a86a9be9-ce50-4e51-b68f-3b97e9fdb795", "type": "subtopic", "title": "Trafficking Definitions", "children": [{"id": "48286edf-1211-4dd4-995a-e3cffd81afa5", "type": "concept", "title": "Sex trafficking"}, {"id": "fb63937f-379e-4aea-9e86-637473f1fb36", "type": "concept", "title": "Labor trafficking"}, {"id": "243ec012-4706-49fe-9ffd-d331d7677da2", "type": "concept", "title": "Commercial sexual exploitation of minors"}], "description": "Students learn force, fraud, coercion, and legal distinctions."}, {"id": "8132a280-0014-4638-b4f6-d7446c6e3840", "type": "subtopic", "title": "Recruitment and Control", "children": [{"id": "23d37f42-ca40-45da-8a7b-8cbb154ddf53", "type": "concept", "title": "Debt and threats"}, {"id": "c69ea4eb-3326-4499-b163-23933fecbcfc", "type": "concept", "title": "Isolation"}, {"id": "12e4ff7b-61fc-45e8-9084-8fab39b94727", "type": "concept", "title": "Immigration and documents"}], "description": "The gist is to understand how exploiters create dependency."}, {"id": "49ad71ad-7070-4a38-860b-ad4a09aa278a", "type": "subtopic", "title": "Survivor-Centered Response", "children": [{"id": "46ea16ba-92c6-412a-8d40-071aa76b9884", "type": "concept", "title": "Housing and legal needs"}, {"id": "494ab23e-e6be-45c7-b37d-b90bab8f29d1", "type": "concept", "title": "Language access"}, {"id": "487dc2f8-b4ba-499d-b0bb-0a3a5f1cbca6", "type": "concept", "title": "Noncriminalization principles"}], "description": "Students evaluate safety, trust, and long-term stabilization."}]}, {"id": "b05d89f0-2beb-410c-a4a9-bdbc2c74ebb5", "type": "topic", "title": "Hate Crime, Bias Victimization, Community Violence, Mass Violence, and Terrorism", "description": "Some victimization targets identity, community, or public life. Students learn individual and collective harm, community trauma, and mass-violence response.", "children": [{"id": "45d84e90-5e29-4832-a200-df4df9e5c940", "type": "subtopic", "title": "Bias Victimization", "children": [{"id": "284d79fd-7fbc-4b30-863b-1cf7af989558", "type": "concept", "title": "Bias motivation"}, {"id": "d08af721-dccd-4ac3-9f0f-0f384622c843", "type": "concept", "title": "Symbolic harm"}, {"id": "a5a5e45b-27c5-4456-a715-c26041fe2f91", "type": "concept", "title": "Reporting barriers"}], "description": "Students learn how hate crimes affect both individuals and communities."}, {"id": "24d922ac-6717-4fc2-bd62-b468307e0161", "type": "subtopic", "title": "Community and Gun Violence", "children": [{"id": "8943d288-f7ed-4617-a207-539dd6987af9", "type": "concept", "title": "Retaliation cycles"}, {"id": "786bd544-98b8-44af-bef1-2385d83c7890", "type": "concept", "title": "Community violence interruption"}, {"id": "6de604d6-2b7e-4aad-84fb-722b5b8747e7", "type": "concept", "title": "Public health framing"}], "description": "The point is to analyze concentrated violence and neighborhood trauma."}, {"id": "0f7868ec-37e1-4cc7-987e-b97e730090d0", "type": "subtopic", "title": "Mass Violence and Terrorism", "children": [{"id": "9c7b1372-a55c-4d66-9031-452a8a3f1888", "type": "concept", "title": "Family assistance centers"}, {"id": "38ae17ff-d766-434a-967e-b664c71edb20", "type": "concept", "title": "Long-term recovery"}, {"id": "4f429b42-caf6-405f-bb63-99f4d5c8ca35", "type": "concept", "title": "Memorialization and media"}], "description": "Students learn coordinated response after large-scale harm."}]}, {"id": "3b056e03-f3a0-4158-9f4e-9069f4627082", "type": "topic", "title": "Restorative Justice, Procedural Justice, Secondary Victimization, and System Response", "description": "Justice-system response can support or harm victims. Students study procedural justice, restorative options, and secondary victimization.", "children": [{"id": "6782db6b-f740-4c8a-8677-e35d856ec6e9", "type": "subtopic", "title": "Procedural Justice", "children": [{"id": "b8d0452b-6aed-41cd-8094-9d76d89cae09", "type": "concept", "title": "Voice and validation"}, {"id": "ab4f64cd-680f-442a-bf53-646dd1845052", "type": "concept", "title": "Transparency"}, {"id": "4f212b61-d950-48b5-a9a9-8e55ee0b3a6c", "type": "concept", "title": "Legitimacy"}], "description": "Students learn why voice, respect, neutrality, and trust matter."}, {"id": "fd2ce9d0-c430-4f29-83d2-ef73d0d3e424", "type": "subtopic", "title": "Secondary Victimization", "children": [{"id": "8d96b4a0-856f-4cbd-bd3a-3ddd1c360c87", "type": "concept", "title": "Disbelief and blame"}, {"id": "f03f84b2-e645-46d3-89e0-b1ea7981bbd3", "type": "concept", "title": "Delay and confusion"}, {"id": "854d5321-8f55-4300-8394-df6bbfe2bec6", "type": "concept", "title": "Insensitive questioning"}], "description": "The gist is to identify system behaviors that deepen harm."}, {"id": "19ecdb3d-f7dd-4e16-b03e-a88d3935483b", "type": "subtopic", "title": "Restorative Justice", "children": [{"id": "7ef8b8b0-220e-47ef-a63a-ab955a39e5ca", "type": "concept", "title": "Preparation and consent"}, {"id": "4c4f2883-5b48-45e5-aa34-06ed5e7fad8f", "type": "concept", "title": "Accountability"}, {"id": "fb67194a-7b37-4219-b923-44e47b08a22a", "type": "concept", "title": "Power and safety concerns"}], "description": "Students evaluate repair-focused processes."}]}, {"id": "9f1ed81d-299f-4b8e-8ea2-67c6ac18e513", "type": "topic", "title": "Equity, Cultural Humility, Tribal, Immigrant, LGBTQ+, Rural, and Underserved Victims", "description": "Victim services must be accessible and culturally responsive. Students learn how systems can exclude people and how equity-centered design improves response.", "children": [{"id": "24859af3-c472-4db8-8a19-a983e2bc059a", "type": "subtopic", "title": "Cultural Humility", "children": [{"id": "3e38f848-643c-44b3-96e5-6908dabe5b2c", "type": "concept", "title": "Self-reflection"}, {"id": "fd2d97d5-5d0e-4b2a-94b7-1f01baacb352", "type": "concept", "title": "Power awareness"}, {"id": "508daa5b-0502-47a4-b93b-282afc6133aa", "type": "concept", "title": "Community partnership"}], "description": "Students learn humility as practice, not a checklist."}, {"id": "99e21178-5dec-411b-890d-464cf1f9b2f6", "type": "subtopic", "title": "Underserved Communities", "children": [{"id": "05bb9a70-1756-43f2-b44c-a19f588fc28f", "type": "concept", "title": "Tribal sovereignty"}, {"id": "ee86b792-3cbb-4259-9866-cb079894f80e", "type": "concept", "title": "Immigrant victims"}, {"id": "58f02d19-3783-4de6-aebf-8d86ddf07003", "type": "concept", "title": "LGBTQ+ and disability access"}], "description": "The point is to identify barriers and assets."}, {"id": "d74518f9-1f41-4e3f-982a-65be62a2da06", "type": "subtopic", "title": "Equity-Centered Service Design", "children": [{"id": "a7833ae8-7082-4d10-bfea-efba20114562", "type": "concept", "title": "Language justice"}, {"id": "b124d7c2-d048-4fa2-9686-55b883ae68f9", "type": "concept", "title": "Rural services"}, {"id": "914c5560-aa98-49be-8235-8b55c4e4f89d", "type": "concept", "title": "Administrative burden"}], "description": "Students apply access principles to real programs."}]}, {"id": "9a637b6b-f25f-4f57-a350-08bd13793d7c", "type": "topic", "title": "Evaluation, Prevention, Vicarious Trauma, Ethics, and Capstone Victim Services Design", "description": "The capstone connects victimology to service design and prevention. Students learn to evaluate programs, protect workers, and design survivor-centered systems.", "children": [{"id": "8f44cd42-f3ac-4c9b-b916-fc52761870f6", "type": "subtopic", "title": "Program Evaluation", "children": [{"id": "0acab5fa-003d-4418-a773-8ed5b6f94d55", "type": "concept", "title": "Logic models"}, {"id": "8b299052-d922-426d-8c7d-164a7233878a", "type": "concept", "title": "Process and outcome metrics"}, {"id": "bf4e0da3-46a4-46fe-bf51-54ed542fb5e5", "type": "concept", "title": "Ethical evaluation"}], "description": "Students learn whether victim services are reaching people and improving outcomes."}, {"id": "896ea337-1194-4102-b230-01c387601b66", "type": "subtopic", "title": "Vicarious Trauma", "children": [{"id": "11961309-83e1-4500-94b7-6f964927497d", "type": "concept", "title": "Burnout and compassion fatigue"}, {"id": "dc5872d1-9dfd-40a0-aa0d-a4ca8aff5ae4", "type": "concept", "title": "Supervision"}, {"id": "208c8986-8e94-4bdf-ac7d-44992d382177", "type": "concept", "title": "Organizational readiness"}], "description": "The gist is to protect helpers and organizations from cumulative trauma exposure."}, {"id": "885824ce-49f3-40eb-a377-663232164614", "type": "subtopic", "title": "Capstone Design", "children": [{"id": "0a8bce8f-0b54-45ac-b914-01b2f1481b05", "type": "concept", "title": "Needs assessment"}, {"id": "c85262e4-4842-41d5-987c-8c44e4ed0db1", "type": "concept", "title": "Trauma-informed model"}, {"id": "87ca5970-debd-4ae8-b1ae-9363a4d96767", "type": "concept", "title": "Evaluation and sustainability"}], "description": "Students synthesize course learning into an applied service proposal."}]}], "dbBacked": true}$victjson$::jsonb,
