update public.learning_paths
set
  title = 'Victimology',
  goal = 'Victimology',
  summary = 'Victimology examines the experience, measurement, causes, consequences, rights, and social response to criminal victimization in the United States. The course covers victimization data, theories, trauma and recovery, victims'' rights, compensation and restitution, advocacy and case management, intimate partner violence, sexual violence, child and youth victimization, elder abuse, disability, human trafficking, hate crime, community and mass violence, restorative justice, secondary victimization, equity, cultural humility, vicarious trauma, and victim-service evaluation.',
  data = $victjson${"slug": "victimology", "title": "Victimology", "description": "Victimology examines the experience, measurement, causes, consequences, rights, and social response to criminal victimization in the United States. The course covers victimization data, theories, trauma and recovery, victims' rights, compensation and restitution, advocacy and case management, intimate partner violence, sexual violence, child and youth victimization, elder abuse, disability, human trafficking, hate crime, community and mass violence, restorative justice, secondary victimization, equity, cultural humility, vicarious trauma, and victim-service evaluation.", "topics": [{"id": "24849253-5265-4445-b3a9-31dad5012219", "type": "topic", "title": "Foundations of Victimology: History, Scope, Concepts, and Debates", "description": "This opening unit introduces victimology as the study of victimization, harm, rights, services, and social response. Students learn how the field emerged and why it must avoid victim blaming while still explaining patterns of risk.", "children": [{"id": "fc40959d-01ac-4509-8e69-63983b8dd0ba", "type": "subtopic", "title": "Origins and Scope", "children": [{"id": "f6891eba-37b1-42d8-b7af-0a4500b4b62b", "type": "concept", "title": "Victims' rights movement"}, {"id": "0bb0a153-24f7-4a3c-9086-122d4cd3918d", "type": "concept", "title": "Victim services field"}, {"id": "e2dfebe3-e440-42c9-82a7-91f92c12f08f", "type": "concept", "title": "Academic and applied victimology"}], "description": "Students learn how victimology developed from criminology, victims' rights movements, and social-service practice."}, {"id": "cedb6298-87ec-4261-b601-c4a13e82ffdf", "type": "subtopic", "title": "Key Concepts", "children": [{"id": "da44793b-a385-4f27-a52f-c46a7d2ac036", "type": "concept", "title": "Victim versus survivor language"}, {"id": "91d9edbd-8148-41fa-9b04-67c03a7dff83", "type": "concept", "title": "Direct and indirect victims"}, {"id": "10b4657d-d34e-453f-a46f-388279e0d88d", "type": "concept", "title": "Social harm and criminal harm"}], "description": "The gist is to define victim, survivor, harm, vulnerability, and resilience carefully."}, {"id": "40bdb560-c088-46cf-824b-a19e3930093f", "type": "subtopic", "title": "Core Debates", "children": [{"id": "08301776-6ca7-4159-a86a-31e99461f3c3", "type": "concept", "title": "Victim blaming"}, {"id": "3ed83866-dd38-41c5-bdf6-814bddce7574", "type": "concept", "title": "Agency and vulnerability"}, {"id": "a7295ec7-03a4-4d94-8a8b-32d144ad9dc7", "type": "concept", "title": "Punishment versus healing"}], "description": "Students examine tensions in the field."}]}, {"id": "407c0e73-bf5a-4c7e-94db-79d86429853f", "type": "topic", "title": "Measuring Victimization: NCVS, Police Data, Self-Report, and Hidden Victimization", "description": "Measurement determines whose harm is visible. Students learn how official reports, victimization surveys, and qualitative accounts reveal different parts of victimization.", "children": [{"id": "5f77da48-49a6-4bf1-a159-0e8320f34a7a", "type": "subtopic", "title": "NCVS and Victimization Surveys", "children": [{"id": "f146b2a0-6e6c-4888-a3ff-50ed139538ba", "type": "concept", "title": "Prevalence and incidence"}, {"id": "88ad1dc6-2b0d-4660-87d7-c2437c6590de", "type": "concept", "title": "Household and personal crimes"}, {"id": "6d889db6-3fb4-40c0-96d7-e80327b683ed", "type": "concept", "title": "Survey design and recall"}], "description": "Students learn how the NCVS captures reported and unreported victimization."}, {"id": "c870a699-aeb2-45de-b5c9-7e9a7e34bf35", "type": "subtopic", "title": "Police and Administrative Data", "children": [{"id": "812776cf-6068-41b7-824b-80391bf6824a", "type": "concept", "title": "UCR/NIBRS"}, {"id": "c6c72414-fda4-49c4-a4e9-35399980ea06", "type": "concept", "title": "Reporting and clearance"}, {"id": "2c85142b-896b-4e45-b969-269760f8d29e", "type": "concept", "title": "Service and compensation data"}], "description": "The point is to compare reported-crime data with victimization data."}, {"id": "799050e3-efa1-4a7f-9174-fb86b29f9e21", "type": "subtopic", "title": "Hidden Victimization", "children": [{"id": "bf48aebd-b5cb-47a1-8c99-9f69cf164eab", "type": "concept", "title": "Stigma and fear"}, {"id": "b73bfab6-3687-4e3e-bf1c-8df74c0c1b67", "type": "concept", "title": "Power-dependent abuse"}, {"id": "fed5ab69-bbb8-4369-91e6-6a38f940cc67", "type": "concept", "title": "Language and access barriers"}], "description": "Students learn why some harms stay invisible."}]}, {"id": "5dd9330a-77ac-457a-ae39-cdb441c8bd43", "type": "topic", "title": "Theories of Victimization and Victim-Offender Relationships", "description": "This unit explains patterns of victimization without blaming victims. Students learn theories of exposure, opportunity, repeat victimization, and victim-offender overlap.", "children": [{"id": "c2bf37ba-a678-46ef-9ae4-5faff02b78c1", "type": "subtopic", "title": "Lifestyle and Routine Activities", "children": [{"id": "9438cc95-6cc8-4702-8dbd-fe30be50a07e", "type": "concept", "title": "Suitable targets"}, {"id": "d69c9d9d-3fb7-4284-929f-744ef9efd79c", "type": "concept", "title": "Guardianship"}, {"id": "ac0a12b0-6a04-4b67-ac07-0fe4e91357ce", "type": "concept", "title": "Time and place"}], "description": "Students examine how routine patterns affect risk exposure."}, {"id": "9fdefa67-84a5-4d69-83b3-4a722e3b7a8f", "type": "subtopic", "title": "Repeat Victimization", "children": [{"id": "c3bc152a-4f2d-42ad-8808-2a66fbbd434b", "type": "concept", "title": "Near repeats"}, {"id": "513dda32-5ba9-441a-99af-1179c825daf6", "type": "concept", "title": "Chronic victimization"}, {"id": "de8850f5-81b9-4a27-b693-8254c6932254", "type": "concept", "title": "Prevention targeting"}], "description": "The gist is to understand why victimization can cluster over time and place."}, {"id": "1e9e1d3f-8ffd-48aa-a950-9034d20d5b96", "type": "subtopic", "title": "Victim-Offender Overlap", "children": [{"id": "228741ff-1f47-45f1-b1ff-6b89cd204961", "type": "concept", "title": "Shared risk factors"}, {"id": "50bbe5b3-5a6c-4c66-8c40-5dd5470fd0aa", "type": "concept", "title": "Retaliation cycles"}, {"id": "4980b3b1-939a-4b80-a8c1-38dc8c6e85d8", "type": "concept", "title": "Trauma and justice involvement"}], "description": "Students study the empirical overlap between offending and victimization."}]}, {"id": "86c321f5-bca4-4d5d-9520-60aecbf6f3e6", "type": "topic", "title": "Victim Impact, Trauma, Crisis, Resilience, and Recovery", "description": "Victimization can create psychological, physical, social, and financial harm. Students learn trauma-informed concepts while recognizing resilience and recovery.", "children": [{"id": "4bb3756a-65b8-48f4-9974-f793ae4a3621", "type": "subtopic", "title": "Trauma and Crisis", "children": [{"id": "8c0e2602-28cf-4c61-a8ee-574804d3e054", "type": "concept", "title": "Acute stress"}, {"id": "cd699bab-2744-455e-9641-073fe99e6a5b", "type": "concept", "title": "PTSD"}, {"id": "76dfb6c8-05a9-4170-82a6-5ad7f0afd9fc", "type": "concept", "title": "Grief and loss"}], "description": "Students learn common trauma responses and immediate crisis needs."}, {"id": "0258bce1-a26f-4a68-9ee9-93d51cecfd22", "type": "subtopic", "title": "Resilience and Recovery", "children": [{"id": "0da58eda-d1cf-45f0-86e3-26fd15fb7266", "type": "concept", "title": "Coping and meaning-making"}, {"id": "9a27a4fd-2cfa-441a-83ce-ee0349434c4c", "type": "concept", "title": "Social support"}, {"id": "14cabaae-a794-43a6-b5ae-cbe63c4ce186", "type": "concept", "title": "Posttraumatic growth debates"}], "description": "The point is to avoid reducing people to trauma."}, {"id": "21ef27e5-02dc-4d05-82d5-0de227e694c8", "type": "subtopic", "title": "Trauma-Informed Practice", "children": [{"id": "2dfab30a-bc7a-43ea-9004-488afa5c61b2", "type": "concept", "title": "Safety"}, {"id": "69c0abca-29dd-4630-b9ac-15ee52ff0461", "type": "concept", "title": "Choice and collaboration"}, {"id": "fee830d2-268c-499b-a963-506c10ce9476", "type": "concept", "title": "Empowerment and trust"}], "description": "Students translate trauma knowledge into response principles."}]}, {"id": "870a2e05-aea7-4e44-b27c-799bb0db4bfc", "type": "topic", "title": "Victims' Rights, VOCA, Compensation, Restitution, Notification, and Participation", "description": "This section covers the legal and policy architecture of victim rights in the U.S. Students learn how rights, compensation, restitution, and participation work in practice.", "children": [{"id": "f0b3e221-bf10-44c1-80de-2ff3eaf80e5f", "type": "subtopic", "title": "Victims' Rights Framework", "children": [{"id": "c55c7e5a-3d4c-4482-bad3-1c4a61c643b3", "type": "concept", "title": "Notice and presence"}, {"id": "23d6e417-0cf8-4a00-abe6-d69f2022b03e", "type": "concept", "title": "Victim impact statements"}, {"id": "51043f8d-e166-42bb-b51f-e3f54f36c170", "type": "concept", "title": "Enforcement limits"}], "description": "Students learn federal and state rights to notice, participation, protection, and dignity."}, {"id": "be486fd5-86be-4a5e-8276-6b85795f90c2", "type": "subtopic", "title": "VOCA and Compensation", "children": [{"id": "42fc358d-da3a-40ad-8e53-0979ab8fe10d", "type": "concept", "title": "Crime Victims Fund"}, {"id": "a30ebc3f-bde7-4f27-bcf2-ebcd7c302194", "type": "concept", "title": "State compensation programs"}, {"id": "c7cbd59f-10f7-438b-80ca-b137b5085222", "type": "concept", "title": "Eligibility and documentation"}], "description": "The gist is to understand how victim assistance and compensation systems are funded and administered."}, {"id": "7d591204-683d-47e1-9180-65a054c4a1c3", "type": "subtopic", "title": "Restitution and Participation", "children": [{"id": "9e17e535-3542-4ff9-8f9f-ee435c7d636e", "type": "concept", "title": "Restitution orders"}, {"id": "102a7547-343d-47f2-ba95-419effbe2050", "type": "concept", "title": "Collection barriers"}, {"id": "ee687dc4-a6cb-41c9-99b7-f74b873337ba", "type": "concept", "title": "Procedural fairness"}], "description": "Students examine the promise and limits of monetary and procedural remedies."}]}, {"id": "a3d36fe5-5727-4d15-8eb0-67a5b16a6cb0", "type": "topic", "title": "Victim Services, Advocacy, Case Management, Confidentiality, and Ethics", "description": "Victim services connect people to safety, information, healing, and resources. Students learn service models, ethics, boundaries, and coordinated care.", "children": [{"id": "4e76dc50-bef2-441d-b026-aa2e7ac14d93", "type": "subtopic", "title": "Advocacy Models", "children": [{"id": "f22f40a0-5680-441f-8404-17bd38dcb4bf", "type": "concept", "title": "Crisis intervention"}, {"id": "53bf2b58-7e3e-4d46-b908-9ea51b8f9d15", "type": "concept", "title": "Court advocacy"}, {"id": "60144882-43df-4e43-9419-abd647193a93", "type": "concept", "title": "Community-based services"}], "description": "Students compare crisis, systems, legal, and community advocacy."}, {"id": "d4cd3fbb-8808-4d8e-aada-e17971ff5a18", "type": "subtopic", "title": "Case Management and Referrals", "children": [{"id": "97e75c6a-562a-41c9-adce-7b2cce3fa6cc", "type": "concept", "title": "Needs assessment"}, {"id": "591b3b5a-74c8-4cea-8a78-f654aba10724", "type": "concept", "title": "Warm referrals"}, {"id": "1b0d559b-126c-478f-8758-c5caee6a8e80", "type": "concept", "title": "Safety and resource planning"}], "description": "The point is to build practical service-navigation skill."}, {"id": "39b125a8-c77b-48a0-98b8-8aa99aef00f3", "type": "subtopic", "title": "Ethics and Confidentiality", "children": [{"id": "d13a1769-04a9-482d-8167-6b39724c809e", "type": "concept", "title": "Informed consent"}, {"id": "abb72e03-1fe0-4f16-8f1d-03c777087821", "type": "concept", "title": "Mandated reporting"}, {"id": "39e0c66a-ea81-430c-a650-597eda0093f5", "type": "concept", "title": "Documentation and boundaries"}], "description": "Students learn ethical duties in helping relationships."}]}, {"id": "68595452-9653-4137-9485-e97e370ff1de", "type": "topic", "title": "Intimate Partner Violence, Coercive Control, Stalking, and Lethality Risk", "description": "This unit studies abuse within intimate relationships and the systems that respond to it. Students learn coercive control, safety planning, and risk assessment.", "children": [{"id": "2fc1ce81-38be-4d9c-be31-199dbc1f867b", "type": "subtopic", "title": "Dynamics of IPV", "children": [{"id": "7ff17b40-0b90-4c71-80db-f7c8e7bd4744", "type": "concept", "title": "Power and control"}, {"id": "c4207302-7d34-4709-a940-21bcb05d1c4d", "type": "concept", "title": "Cycle-of-violence critiques"}, {"id": "ea6cdc34-b899-4c64-b6f2-e96efc1c341e", "type": "concept", "title": "Economic abuse"}], "description": "Students learn why abuse is often patterned, strategic, and relational."}, {"id": "ff28d534-fe05-492c-8dcf-095fcbc2d584", "type": "subtopic", "title": "Stalking and Lethality", "children": [{"id": "45148dc0-4dff-4eb8-b2a4-775d02c565e4", "type": "concept", "title": "Threats and weapons"}, {"id": "78728518-30c9-48fb-9744-6da9b19647c0", "type": "concept", "title": "Separation risk"}, {"id": "39b1561f-54ca-4e51-9558-de3d7a9f6af3", "type": "concept", "title": "Stalking behaviors"}], "description": "The gist is to identify escalation and high-risk indicators."}, {"id": "507c0ef5-711f-4b76-a980-576830ec2146", "type": "subtopic", "title": "Safety Planning and Systems Response", "children": [{"id": "9a6817ee-3fb8-4d6f-bde3-d47611b4ac2b", "type": "concept", "title": "Protective orders"}, {"id": "559deef8-e659-4ce5-ab1d-3e286dfa905b", "type": "concept", "title": "Shelter and housing"}, {"id": "16b2052c-56c0-426d-bc50-d6fa6a61e1b0", "type": "concept", "title": "Coordinated community response"}], "description": "Students connect advocacy with legal and social-service options."}]}, {"id": "cd03755e-d517-414f-a445-820d0f2cec89", "type": "topic", "title": "Sexual Violence, SANE/SART, Campus/Military Contexts, Consent, and Secondary Harm", "description": "Sexual violence requires trauma-informed, evidence-aware, and survivor-centered response. Students learn reporting choices, forensic systems, and institutional harms.", "children": [{"id": "c5bf0d43-3204-4c30-afb8-f2503e7b0a2b", "type": "subtopic", "title": "Sexual Violence Dynamics", "children": [{"id": "4a0f702c-523f-4b95-b666-e7d43fd6a2d7", "type": "concept", "title": "Consent and coercion"}, {"id": "44d3081c-f34c-445d-b007-1841964522d0", "type": "concept", "title": "Acquaintance assault"}, {"id": "fce584d7-a7db-494e-b5a9-4cdda97ee23e", "type": "concept", "title": "Rape myths"}], "description": "Students learn prevalence, myths, consent, and offender/victim relationship patterns."}, {"id": "cf79444e-1533-4e5c-9043-0a76f917da96", "type": "subtopic", "title": "SANE/SART Response", "children": [{"id": "03c23290-b216-4082-bc2d-17925c3bd0c6", "type": "concept", "title": "Forensic exams"}, {"id": "6f539f92-e413-4463-b34e-a5331847348f", "type": "concept", "title": "Medical advocacy"}, {"id": "73aa7cca-9c29-4c96-81e9-a5890f6f9c04", "type": "concept", "title": "Evidence and autonomy"}], "description": "The point is to understand multidisciplinary response."}, {"id": "403ff644-d601-4101-a468-3beb69a62468", "type": "subtopic", "title": "Institutional and Secondary Harm", "children": [{"id": "10690d2a-d1e9-4916-944e-899eef2f28d8", "type": "concept", "title": "Campus processes"}, {"id": "a63cfe95-f918-4082-a58b-373cfc177281", "type": "concept", "title": "Military context"}, {"id": "a4ece800-befd-43d0-a857-7c562315df70", "type": "concept", "title": "Victim credibility and backlash"}], "description": "Students analyze how systems can retraumatize survivors."}]}, {"id": "6560a1ef-5f0c-4f2c-a1a1-e2d2209b6bad", "type": "topic", "title": "Child Maltreatment, Youth Victimization, ACEs, and Juvenile Justice Intersections", "description": "Children and youth experience victimization in developmentally distinct ways. Students learn maltreatment, ACEs, mandated reporting, and youth justice intersections.", "children": [{"id": "1efae6b0-511e-4968-8dcd-02e8ca1415bd", "type": "subtopic", "title": "Child Abuse and Neglect", "children": [{"id": "6bd9f7dd-0df8-43fe-8e11-020af39d42c1", "type": "concept", "title": "Physical abuse"}, {"id": "163f954f-bd08-4292-9db2-7e54027fbb5c", "type": "concept", "title": "Sexual abuse"}, {"id": "cdaea65c-5ce0-43b4-b3ac-73e5224556b2", "type": "concept", "title": "Neglect and emotional abuse"}], "description": "Students learn categories, indicators, and reporting obligations."}, {"id": "f865835f-2ffc-4bb5-88b5-744af5fd2b83", "type": "subtopic", "title": "ACEs and Development", "children": [{"id": "5c1cbe40-b1d4-4e15-bdff-0c740e6c5574", "type": "concept", "title": "Toxic stress"}, {"id": "f3814f41-ee8e-4b96-961c-3ba5daf16e5c", "type": "concept", "title": "Protective factors"}, {"id": "0f3af648-517e-49c7-9c1f-d615583e1578", "type": "concept", "title": "Intergenerational trauma"}], "description": "The gist is to connect early adversity to health, behavior, and justice outcomes."}, {"id": "8648320e-35df-4cb7-9407-d0cfaa9fa296", "type": "subtopic", "title": "Youth Systems", "children": [{"id": "9068cfeb-be17-4aef-a799-28ba6c9a59a4", "type": "concept", "title": "School-to-prison pipeline"}, {"id": "1f332b1e-5600-4c06-99e5-6537416e74df", "type": "concept", "title": "Crossover youth"}, {"id": "49d1fdda-d129-4d03-b8a1-80eaaeaadea1", "type": "concept", "title": "Diversion and family services"}], "description": "Students examine schools, child welfare, and juvenile justice."}]}, {"id": "4027b3ff-3cb8-4008-a625-e770511dfd14", "type": "topic", "title": "Elder Abuse, Disability, Vulnerable Adults, and Guardianship-Related Victimization", "description": "This unit focuses on victimization of older adults and people with disabilities. Students learn capacity, dependence, exploitation, and service barriers.", "children": [{"id": "843e32db-e701-4b8d-b5bc-354b07121086", "type": "subtopic", "title": "Elder Abuse", "children": [{"id": "c351b9ac-afe5-4187-a6bb-dfe73d471f6e", "type": "concept", "title": "Physical and emotional abuse"}, {"id": "9b8d43af-52c1-41d3-bfe1-28b98ce4d8d2", "type": "concept", "title": "Neglect"}, {"id": "d092f6e5-ade8-407f-a3ad-368b32f53a4e", "type": "concept", "title": "Financial exploitation"}], "description": "Students learn common forms and detection challenges."}, {"id": "bbf776f8-a939-436c-8c8e-1336ab68aa32", "type": "subtopic", "title": "Disability and Vulnerability", "children": [{"id": "3bc91a0d-d448-40f0-a214-e45e636f8956", "type": "concept", "title": "Communication access"}, {"id": "ef5b4b4e-b60c-49c8-8c39-beedcf447db9", "type": "concept", "title": "Caregiver dependence"}, {"id": "6eeed492-e9e8-4d47-8cfa-7ea75e631dd1", "type": "concept", "title": "Institutional abuse"}], "description": "The point is to understand access, autonomy, and abuse risk without paternalism."}, {"id": "e98c53e4-5893-4581-b727-d505a5240bf6", "type": "subtopic", "title": "Adult Protective and Legal Systems", "children": [{"id": "3385ba32-ea53-4764-9be2-83ee76ba87c3", "type": "concept", "title": "Capacity and consent"}, {"id": "d349510d-ea04-4da2-ba72-95a6988b0767", "type": "concept", "title": "Guardianship abuse"}, {"id": "6a80e6e8-61a9-45b8-a4d5-32b9ecad8253", "type": "concept", "title": "Mandatory reporting and APS"}], "description": "Students connect victim needs with legal remedies."}]}, {"id": "f600b932-a211-4382-95a6-323ca6ddd069", "type": "topic", "title": "Human Trafficking, Labor Exploitation, Sex Trafficking, and Migrant Victimization", "description": "Trafficking and exploitation involve coercion, dependency, and structural vulnerability. Students learn indicators, service needs, and survivor-centered response.", "children": [{"id": "a86a9be9-ce50-4e51-b68f-3b97e9fdb795", "type": "subtopic", "title": "Trafficking Definitions", "children": [{"id": "48286edf-1211-4dd4-995a-e3cffd81afa5", "type": "concept", "title": "Sex trafficking"}, {"id": "fb63937f-379e-4aea-9e86-637473f1fb36", "type": "concept", "title": "Labor trafficking"}, {"id": "243ec012-4706-49fe-9ffd-d331d7677da2", "type": "concept", "title": "Commercial sexual exploitation of minors"}], "description": "Students learn force, fraud, coercion, and legal distinctions."}, {"id": "8132a280-0014-4638-b4f6-d7446c6e3840", "type": "subtopic", "title": "Recruitment and Control", "children": [{"id": "23d37f42-ca40-45da-8a7b-8cbb154ddf53", "type": "concept", "title": "Debt and threats"}, {"id": "c69ea4eb-3326-4499-b163-23933fecbcfc", "type": "concept", "title": "Isolation"}, {"id": "12e4ff7b-61fc-45e8-9084-8fab39b94727", "type": "concept", "title": "Immigration and documents"}], "description": "The gist is to understand how exploiters create dependency."}, {"id": "49ad71ad-7070-4a38-860b-ad4a09aa278a", "type": "subtopic", "title": "Survivor-Centered Response", "children": [{"id": "46ea16ba-92c6-412a-8d40-071aa76b9884", "type": "concept", "title": "Housing and legal needs"}, {"id": "494ab23e-e6be-45c7-b37d-b90bab8f29d1", "type": "concept", "title": "Language access"}, {"id": "487dc2f8-b4ba-499d-b0bb-0a3a5f1cbca6", "type": "concept", "title": "Noncriminalization principles"}], "description": "Students evaluate safety, trust, and long-term stabilization."}]}, {"id": "b05d89f0-2beb-410c-a4a9-bdbc2c74ebb5", "type": "topic", "title": "Hate Crime, Bias Victimization, Community Violence, Mass Violence, and Terrorism", "description": "Some victimization targets identity, community, or public life. Students learn individual and collective harm, community trauma, and mass-violence response.", "children": [{"id": "45d84e90-5e29-4832-a200-df4df9e5c940", "type": "subtopic", "title": "Bias Victimization", "children": [{"id": "284d79fd-7fbc-4b30-863b-1cf7af989558", "type": "concept", "title": "Bias motivation"}, {"id": "d08af721-dccd-4ac3-9f0f-0f384622c843", "type": "concept", "title": "Symbolic harm"}, {"id": "a5a5e45b-27c5-4456-a715-c26041fe2f91", "type": "concept", "title": "Reporting barriers"}], "description": "Students learn how hate crimes affect both individuals and communities."}, {"id": "24d922ac-6717-4fc2-bd62-b468307e0161", "type": "subtopic", "title": "Community and Gun Violence", "children": [{"id": "8943d288-f7ed-4617-a207-539dd6987af9", "type": "concept", "title": "Retaliation cycles"}, {"id": "786bd544-98b8-44af-bef1-2385d83c7890", "type": "concept", "title": "Community violence interruption"}, {"id": "6de604d6-2b7e-4aad-84fb-722b5b8747e7", "type": "concept", "title": "Public health framing"}], "description": "The point is to analyze concentrated violence and neighborhood trauma."}, {"id": "0f7868ec-37e1-4cc7-987e-b97e730090d0", "type": "subtopic", "title": "Mass Violence and Terrorism", "children": [{"id": "9c7b1372-a55c-4d66-9031-452a8a3f1888", "type": "concept", "title": "Family assistance centers"}, {"id": "38ae17ff-d766-434a-967e-b664c71edb20", "type": "concept", "title": "Long-term recovery"}, {"id": "4f429b42-caf6-405f-bb63-99f4d5c8ca35", "type": "concept", "title": "Memorialization and media"}], "description": "Students learn coordinated response after large-scale harm."}]}, {"id": "3b056e03-f3a0-4158-9f4e-9069f4627082", "type": "topic", "title": "Restorative Justice, Procedural Justice, Secondary Victimization, and System Response", "description": "Justice-system response can support or harm victims. Students study procedural justice, restorative options, and secondary victimization.", "children": [{"id": "6782db6b-f740-4c8a-8677-e35d856ec6e9", "type": "subtopic", "title": "Procedural Justice", "children": [{"id": "b8d0452b-6aed-41cd-8094-9d76d89cae09", "type": "concept", "title": "Voice and validation"}, {"id": "ab4f64cd-680f-442a-bf53-646dd1845052", "type": "concept", "title": "Transparency"}, {"id": "4f212b61-d950-48b5-a9a9-8e55ee0b3a6c", "type": "concept", "title": "Legitimacy"}], "description": "Students learn why voice, respect, neutrality, and trust matter."}, {"id": "fd2ce9d0-c430-4f29-83d2-ef73d0d3e424", "type": "subtopic", "title": "Secondary Victimization", "children": [{"i